type ShapeKind = "circle" | "square";

const builders = {
  circle: () => new Circle(1.0),
  square: () => new Square(2.0),
} satisfies Record<ShapeKind, () => Shape>;

export function create(kind: ShapeKind): Shape {
  const build = builders[kind];
  if (!build) throw new Error(`unknown shape: ${kind}`);
  return build();
}
